PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE courses(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, date TEXT, time TEXT, kind TEXT DEFAULT 'exam');
CREATE TABLE topics(id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER NOT NULL, title TEXT NOT NULL, done INTEGER DEFAULT 0, mins INTEGER DEFAULT 45, diff TEXT DEFAULT 'medium');
CREATE TABLE quizzes(id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER NOT NULL, title TEXT NOT NULL, date TEXT, done INTEGER DEFAULT 0);
CREATE TABLE qt(id INTEGER PRIMARY KEY AUTOINCREMENT, quiz_id INTEGER NOT NULL, topic_id INTEGER NOT NULL);
CREATE TABLE tasks(id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER, title TEXT NOT NULL, kind TEXT DEFAULT 'todo', due TEXT, done INTEGER DEFAULT 0, area_id INTEGER, est INTEGER, diff TEXT DEFAULT 'medium', done_at TEXT);
CREATE TABLE blocks(id INTEGER PRIMARY KEY AUTOINCREMENT, day TEXT NOT NULL, start TEXT NOT NULL, mins INTEGER DEFAULT 45, kind TEXT DEFAULT 'fixed', title TEXT, ref_kind TEXT, ref_id INTEGER, done INTEGER DEFAULT 0);
CREATE TABLE sessions(id INTEGER PRIMARY KEY AUTOINCREMENT, day TEXT NOT NULL, start_at INTEGER, start TEXT, plan_mins INTEGER DEFAULT 0, act_mins INTEGER DEFAULT 0, pauses INTEGER DEFAULT 0, end_kind TEXT DEFAULT 'open', rating INTEGER, ref_kind TEXT, ref_id INTEGER, diff TEXT);
CREATE TABLE habits(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, area_id INTEGER);
CREATE TABLE hlog(id INTEGER PRIMARY KEY AUTOINCREMENT, habit_id INTEGER NOT NULL, day TEXT NOT NULL, UNIQUE(habit_id, day));
CREATE TABLE dump(id INTEGER PRIMARY KEY AUTOINCREMENT, text TEXT NOT NULL, done INTEGER DEFAULT 0);
CREATE TABLE notes(id INTEGER PRIMARY KEY AUTOINCREMENT, area_id INTEGER, text TEXT NOT NULL);
CREATE TABLE areas(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, color TEXT, sort INTEGER DEFAULT 0);
CREATE TABLE rem(id INTEGER PRIMARY KEY AUTOINCREMENT, text TEXT NOT NULL, at TEXT, done INTEGER DEFAULT 0);
CREATE TABLE goals(id INTEGER PRIMARY KEY AUTOINCREMENT, area_id INTEGER, title TEXT NOT NULL, why TEXT, done INTEGER DEFAULT 0);
CREATE TABLE steps(id INTEGER PRIMARY KEY AUTOINCREMENT, goal_id INTEGER NOT NULL, title TEXT NOT NULL, done INTEGER DEFAULT 0, sort INTEGER DEFAULT 0);
CREATE TABLE prefs(id INTEGER PRIMARY KEY AUTOINCREMENT, k TEXT NOT NULL UNIQUE, v TEXT);
CREATE TABLE log(id INTEGER PRIMARY KEY AUTOINCREMENT, day TEXT NOT NULL, kind TEXT, text TEXT, mins INTEGER DEFAULT 0);
